<?php
use App\Core\{Database as DB,Validator as V};use App\Services\StudentService as S;
$id=V::optInt($_GET['id']??$_GET['subject_id']??null,'Subject');$courses=$id?S::courses($student,[$id]):[];$selected=null;
foreach($courses as $course){if((int)$course['id']===$id){$selected=$course;break;}}if($id&&!$selected){forbidden();}
page_header($selected?'Course modules':'My Courses');
if(!$selected): $filter=is_string($_GET['filter']??null)?$_GET['filter']:'all';$search=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';$coursePage=S::coursePage($student,$search,$filter,(int)($_GET['page']??1));$courses=$coursePage['courses']; ?>
<form method="get" class="filter-bar"><label class="search-field"><?= e(tr('Search courses')) ?><input name="q" value="<?= e($search) ?>" maxlength="100"></label><label><?= e(tr('Status')) ?><select name="filter"><option value="all"<?= selected('all',$filter) ?>><?= e(tr('All')) ?></option><option value="progress"<?= selected('progress',$filter) ?>><?= e(tr('in_progress')) ?></option><option value="complete"<?= selected('complete',$filter) ?>><?= e(tr('Completed')) ?></option></select></label><button class="btn"><?= icon('search') ?><?= e(tr('Search')) ?></button></form><div class="course-grid">
<?php $found=0;foreach($courses as $course){if($search!==''&&mb_stripos($course['name'].' '.$course['code'],$search)===false)continue;if($filter==='complete'&&$course['enrolment_status']!=='completed'&&$course['percent']!==100)continue;if($filter==='progress'&&($course['enrolment_status']==='completed'||$course['percent']<=0||$course['percent']>=100))continue;$found++;require APP_ROOT.'/app/Views/student_course_card.php';} ?></div><?php if(!$found): ?><div class="card empty-state"><?= icon('book') ?><p><?= e(tr('No results found.')) ?></p></div><?php endif; ?>
<div class="pagination"><span><?= $coursePage['total'] ?> <?= e(tr('My Courses')) ?></span><nav><?php foreach(['Previous'=>$coursePage['page']-1,'Next'=>$coursePage['page']+1] as $label=>$n):if($n<1||$n>$coursePage['pages'])continue; ?><a class="btn" href="?<?= e(http_build_query(array_merge($_GET,['page'=>$n]))) ?>"><?= e(tr($label)) ?></a><?php endforeach; ?></nav></div>
<?php else: ?>
<div class="toolbar"><div><a href="courses.php">← <?= e(tr('Back to courses')) ?></a><h2 class="spaced"><?= e($selected['name']) ?></h2><small class="muted"><?= e($selected['batch_name']??'') ?></small></div><span class="pill ok"><?= (int)$selected['percent'] ?>%</span></div>
<section class="card"><div class="card-heading"><h2><?= e(tr('Modules')) ?></h2><a href="tests.php?subject_id=<?= $id ?>"><?= e(tr('Tests')) ?> →</a></div>
<?php foreach($selected['modules'] as $i=>$m): ?><div class="module-block"><div class="module-row"><span class="module-number <?= $m['passed']?'done':'' ?>"><?= $m['passed']?icon('check'):$i+1 ?></span><div><h3><?= e($m['title']) ?></h3><small><?= e(tr('Week')) ?> <?= (int)$m['week_no'] ?> · <?= $m['lessons_done'] ?> / <?= $m['lessons_total'] ?> <?= e(tr('Lessons')) ?></small></div><span class="pill <?= $m['passed']?'ok':'' ?>"><?= e(tr($m['passed']?'Completed':($m['unlocked']?'Available':'Locked'))) ?></span></div>
<?php if($m['unlocked']): ?><div class="lesson-list"><?php foreach($m['lessons'] as $l): ?><div class="lesson-link"><?= icon($l['completed']?'check':($l['unlocked']?'play':'lock')) ?><div><?php if($l['unlocked']): ?><a href="lesson.php?id=<?= (int)$l['id'] ?>"><?= e($l['title']) ?></a><?php else: ?><span><?= e($l['title']) ?></span><?php endif; ?><small><?= e(tr($l['item_type'])) ?> · <?= (int)$l['percent'] ?>%</small></div></div><?php endforeach; ?><?php foreach($m['tests'] as $t): ?><div class="lesson-link"><?= icon('test') ?><a href="tests.php?id=<?= (int)$t['id'] ?>"><?= e($t['title']) ?></a><span class="pill <?= $t['passed']?'ok':'' ?>"><?= e(tr($t['passed']?'pass':'Test')) ?></span></div><?php endforeach; ?></div><?php endif; ?></div><?php endforeach; ?>
<?php if(!$selected['modules']): ?><p class="muted"><?= e(tr('No published modules yet.')) ?></p><?php endif; ?></section><?php endif;page_footer();
